import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex, theme } from 'antd';

import {
	ConversionsChart,
	DashboardCard,
	ReportChart,
	useGetReportsChartQuery,
	useReportsSlice,
} from 'entities/Report';
import { EFilters, prepareDate } from 'features/Filters';
import { IDashboard } from 'pages/Dashboard';
import { useMedia } from 'shared/hooks';
import { OverlayLoader } from 'shared/ui';
import { formatDate } from 'shared/utils';

import styles from './DashboardCharts.module.scss';

interface IDashboardChartsProps extends HTMLAttributes<HTMLDivElement> {
	dashboard?: IDashboard;
	dashboardIsFetching?: boolean;
}

export const DashboardCharts: FC<IDashboardChartsProps> = ({ dashboard, dashboardIsFetching, ...props }) => {
	const { t } = useTranslation();
	const isLg = useMedia('lg');
	const isMd = useMedia();
	const {
		token: { colorBgContainer },
	} = theme.useToken();

	const { chartFilters } = useReportsSlice();
	const searchParams = new URLSearchParams(
		Object.keys(chartFilters).reduce((acc, key) => {
			return chartFilters[key as EFilters] ? { ...acc, [key]: chartFilters[key as EFilters] } : acc;
		}, {}),
	);

	searchParams.set(EFilters.DATE_AFTER, formatDate(prepareDate(new Date(), 29), 'iso') || '');
	searchParams.set(EFilters.DATE_BEFORE, formatDate(prepareDate(new Date()), 'iso') || '');

	const { data, isFetching } = useGetReportsChartQuery(searchParams.toString());

	return (
		<Flex
			vertical
			gap={isMd ? 0 : 8}
			style={{
				backgroundColor: isMd ? colorBgContainer : undefined,
				margin: isMd ? '0 -16px' : undefined,
			}}>
			<Flex
				{...props}
				vertical={isLg}
				gap={isMd ? 0 : 8}
				style={{
					padding: isMd ? '8px 0 0 0' : undefined,
				}}>
				{isFetching && <OverlayLoader />}

				<ReportChart data={data} isDasboard isFetching={isFetching} style={{ width: '100%' }} />

				<div className={styles.conversions}>
					<ConversionsChart dashboard={dashboard} isFetching={dashboardIsFetching} />
				</div>
			</Flex>

			{/*<Flex
				vertical={isMd}
				gap={isMd ? 0 : 8}
				style={{
					padding: isMd ? '8px 0 0 0' : undefined,
				}}>
				<ActionsChart dashboard={dashboard} style={{ width: '100%' }} />
				<RelationsChart dashboard={dashboard} style={{ width: '100%' }} />
			</Flex>*/}

			<div className={styles.cards}>
				{dashboardIsFetching && <OverlayLoader />}

				<DashboardCard
					header={t('Заявки')}
					value={dashboard?.reports?.last_month?.reduce((acc, item) => acc + item.actions_count, 0) || 0}
					oldValue={dashboard?.reports?.previous_month?.reduce((acc, item) => acc + item.actions_count, 0) || 0}
				/>
				<DashboardCard
					header={t('Подключено офферов')}
					value={dashboard?.relations?.last_month?.reduce((acc, item) => acc + item.joined_count, 0) || 0}
					oldValue={dashboard?.relations?.previous_month?.reduce((acc, item) => acc + item.joined_count, 0) || 0}
				/>
				<DashboardCard
					header={t('Клики')}
					value={dashboard?.agg_reports?.last_month?.clicks_count || 0}
					oldValue={dashboard?.agg_reports?.previous_month?.clicks_count || 0}
				/>
				<DashboardCard
					header={t('CR')}
					value={dashboard?.agg_reports?.last_month?.cr || 0}
					oldValue={dashboard?.agg_reports?.previous_month?.cr || 0}
					unit="%"
				/>
			</div>
		</Flex>
	);
};
