import { FC, ReactNode } from 'react';

import { Flex, FlexProps, theme } from 'antd';
import cn from 'classnames';

import ArrowTop from 'assets/images/icons/arrow-top.svg?react';

import styles from './ChangeArrow.module.scss';

interface IChangeArrowProps extends Omit<FlexProps, 'children'> {
	oldValue: number;
	newValue: number;
	isPercent?: boolean;
	label?: ReactNode;
	unit?: string;
}

export const ChangeArrow: FC<IChangeArrowProps> = ({
	className,
	oldValue,
	newValue,
	isPercent,
	label,
	unit,
	...props
}) => {
	const {
		token: { colorTextDescription, colorSuccess, colorError },
	} = theme.useToken();

	const diff = newValue - oldValue;

	return (
		<Flex {...props} gap={2} align="center" className={cn(className, styles.changeArrow)}>
			{label}

			<Flex gap={2} align="center">
				{diff !== 0 && (
					<ArrowTop className={cn(styles.arrow, { [styles.positive]: diff > 0, [styles.negative]: diff < 0 })} />
				)}

				<span
					className={styles.value}
					style={{ color: diff === 0 ? colorTextDescription : diff > 0 ? colorSuccess : colorError }}>
					{isPercent &&
						(oldValue === 0 ? (newValue === 0 ? '0.00%' : `100.00%`) : `${((diff / oldValue) * 100).toFixed(2)}%`)}
					{!isPercent && Math.round((diff + Number.EPSILON) * 100) / 100}
					{unit}
				</span>
			</Flex>
		</Flex>
	);
};
