import { FC, HTMLAttributes, useEffect, useRef, useState } from 'react';
import { useTranslation } from 'react-i18next';
import Carousel from 'react-multi-carousel';

import { Button, Flex, theme } from 'antd';
import cn from 'classnames';

import AngleLeft from 'assets/images/icons/angle-left.svg?react';
import AngleRight from 'assets/images/icons/angle-right.svg?react';
import CloseIcon from 'assets/images/icons/close.svg?react';
import { IBanner, useCloseBannersMutation } from 'pages/Dashboard';
import { useMedia } from 'shared/hooks';
import { PageTitle } from 'shared/ui';

import 'react-multi-carousel/lib/styles.css';

import styles from './DasboardCarousel.module.scss';

interface IDasboardCarouselProps extends HTMLAttributes<HTMLDivElement> {
	banners: IBanner[];
}

export const DasboardCarousel: FC<IDasboardCarouselProps> = ({ banners, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const {
		token: { colorPrimary, colorTextDisabled, colorTextTertiary },
	} = theme.useToken();

	const [closeBanners] = useCloseBannersMutation();

	const containerRef = useRef<HTMLDivElement>(null);
	const [sliderWidth, setSliderWidth] = useState(containerRef.current?.clientWidth || 0);

	useEffect(() => {
		setSliderWidth(containerRef.current?.clientWidth || 0);
	}, [containerRef.current?.clientWidth, banners?.length]);

	useEffect(() => {
		window.addEventListener('resize', () => {
			setSliderWidth(containerRef.current?.clientWidth || 0);
		});
	}, []);

	const sliderRef = useRef<Carousel>(null);
	const [currentSlide, setCurrentSlide] = useState(sliderRef.current?.state.currentSlide);

	useEffect(() => {
		setCurrentSlide(sliderRef.current?.state.currentSlide);
	}, [sliderRef.current?.state.currentSlide]);

	if (!banners?.length) return null;

	return (
		<Flex {...props} vertical gap={8} className={styles.slider} ref={containerRef}>
			<Flex justify="space-between" align="center">
				<PageTitle>{t('Предложения')}</PageTitle>
				<Button
					onClick={() => closeBanners()}
					type="text"
					size="small"
					style={{ width: 28, height: 28, color: colorTextTertiary }}
					icon={<CloseIcon />}
				/>
			</Flex>

			{banners.length > 1 && (
				<>
					<Carousel
						ref={sliderRef}
						afterChange={(_, state) => setCurrentSlide(state.currentSlide)}
						arrows={false}
						draggable={false}
						focusOnSelect={false}
						infinite={false}
						itemClass=""
						keyBoardControl
						minimumTouchDrag={80}
						partialVisible
						pauseOnHover
						renderArrowsWhenDisabled={false}
						renderButtonGroupOutside={false}
						renderDotsOutside={false}
						responsive={{
							desktop: {
								breakpoint: {
									max: 6000,
									min: 767,
								},
								items: 1,
								partialVisibilityGutter: sliderWidth - 688 - 20,
							},
							mobile: {
								breakpoint: {
									max: 767,
									min: 0,
								},
								items: 1,
								partialVisibilityGutter: sliderWidth - 343 - 16,
							},
						}}
						rewind={false}
						rewindWithAnimation={false}
						rtl={false}
						shouldResetAutoplay
						showDots={false}
						sliderClass=""
						slidesToSlide={1}
						swipeable={true}>
						{banners.map((banner) => (
							<div className={styles.slide} key={banner.uuid}>
								<a href={banner.link} target="_blank">
									<img src={isMd ? banner.mobile_image : banner.web_image} height={240} alt="banner" />
								</a>
							</div>
						))}
					</Carousel>

					<Flex gap={12} justify="center" align="center">
						<Button onClick={() => sliderRef.current?.previous(1)} icon={<AngleLeft />} size="small" type="text" />
						{banners.map((banner, i) => (
							<button
								key={banner.uuid}
								onClick={() => sliderRef.current?.goToSlide(i)}
								className={cn(styles.dot, { [styles.active]: currentSlide === i })}
								style={{ backgroundColor: currentSlide === i ? colorPrimary : colorTextDisabled }}
							/>
						))}
						<Button onClick={() => sliderRef.current?.next(1)} icon={<AngleRight />} size="small" type="text" />
					</Flex>
				</>
			)}

			{banners.length === 1 && (
				<div className={styles.slide} style={{ backgroundColor: banners[0].background_color }}>
					<a href={banners[0].link} target="_blank">
						<img src={isMd ? banners[0].mobile_image : banners[0].web_image} height={240} alt="banner" />
					</a>
				</div>
			)}
		</Flex>
	);
};
