import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Pie } from '@ant-design/plots';

import { Card, Divider, Flex, theme, Typography } from 'antd';

import { IDashboard } from 'pages/Dashboard';
import { useMedia } from 'shared/hooks';
import { ChangeArrow, InfoTooltip, OverlayLoader } from 'shared/ui';
import { formatNumber } from 'shared/utils';

import styles from './ConversionsChart.module.scss';

interface IConversionsChartProps extends HTMLAttributes<HTMLDivElement> {
	dashboard?: IDashboard;
	isFetching?: boolean;
}

export const ConversionsChart: FC<IConversionsChartProps> = ({ dashboard, isFetching, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();
	const isLg = useMedia('lg');
	const {
		token: { colorPrimary, purple4 },
	} = theme.useToken();

	const data = {
		cross_sell_count: dashboard?.agg_reports?.last_month?.cross_sell_count || 0,
		direct_sell_count: dashboard?.agg_reports?.last_month?.direct_sell_count || 0,
	};
	const total = data.cross_sell_count + data.direct_sell_count;

	const config = {
		data: [
			{
				type: 'cross',
				value: data.cross_sell_count,
				label: t('Кросс'),
			},
			{
				type: 'direct',
				value: data.direct_sell_count,
				label: t('Прямые'),
			},
		],
		angleField: 'value',
		colorField: 'label',
		innerRadius: 0.75,
		label: false,
		legend: false,
		tooltip: false,
		style: {
			fill: ({ type }: { type: string }) => {
				if (type === 'cross') {
					return purple4;
				}
				return colorPrimary;
			},
		},
	};

	const getPercent = (value: number) => {
		return total > 0 ? Math.round((value / total) * 100) : 0;
	};

	return (
		<Card
			{...props}
			style={{ boxShadow: isMd ? 'none' : undefined, width: '100%', overflow: 'hidden' }}
			styles={{ body: { padding: 0 } }}
			bordered={!isMd}>
			{isFetching && <OverlayLoader />}

			<Flex vertical gap={20} style={{ padding: isMd ? '20px 24px' : '20px' }}>
				<Flex align="center" gap={4}>
					<Typography.Title level={4} style={{ margin: 0 }}>
						{t('Конверсии')}
					</Typography.Title>
				</Flex>

				<div className={styles.chart}>
					<Flex className={styles.total} vertical justify="center" align="center">
						<Typography.Text type="secondary">{t('Всего')}</Typography.Text>
						<Typography.Title level={3} style={{ margin: 0 }}>
							{formatNumber(data.cross_sell_count + data.direct_sell_count)}
						</Typography.Title>
						<ChangeArrow
							isPercent
							oldValue={
								(dashboard?.agg_reports.previous_month.cross_sell_count || 0) +
								(dashboard?.agg_reports.previous_month.direct_sell_count || 0)
							}
							newValue={data.cross_sell_count + data.direct_sell_count}
							label={<Typography.Text style={{ fontSize: 12 }}>{t('за месяц')}</Typography.Text>}
						/>
					</Flex>

					<Pie width={isLg ? 280 : 240} height={isLg ? 280 : 240} padding={0} margin={0} {...config} />
				</div>

				<Flex vertical>
					<Flex align="center" justify="space-between">
						<Typography.Text type="secondary">{t('Прямые')}</Typography.Text>
						<Flex align="center" gap={4}>
							<Typography.Text strong style={{ fontSize: 16, color: colorPrimary }}>
								{formatNumber(data.direct_sell_count)}
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12 }}>
								({getPercent(data.direct_sell_count)}%)
							</Typography.Text>
							<ChangeArrow
								isPercent
								newValue={data.direct_sell_count}
								oldValue={dashboard?.agg_reports.previous_month.direct_sell_count || 0}
							/>
						</Flex>
					</Flex>

					<Divider style={{ margin: 0 }} />

					<Flex align="center" justify="space-between">
						<Flex align="center" gap={4}>
							<Typography.Text type="secondary">{t('Кросс')}</Typography.Text>
							<InfoTooltip
								text={t('Оплата всех целевых действий в рамках одного бренда без привязки к ссылке перехода (оффера).')}
								width={14}
								height={14}
							/>
						</Flex>
						<Flex align="center" gap={4}>
							<Typography.Text strong style={{ fontSize: 16, color: purple4 }}>
								{formatNumber(data.cross_sell_count)}
							</Typography.Text>
							<Typography.Text type="secondary" style={{ fontSize: 12 }}>
								({getPercent(data.cross_sell_count)}%)
							</Typography.Text>
							<ChangeArrow
								isPercent
								newValue={data.cross_sell_count}
								oldValue={dashboard?.agg_reports.previous_month.cross_sell_count || 0}
							/>
						</Flex>
					</Flex>
				</Flex>
			</Flex>
		</Card>
	);
};
