import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { Card, Flex, Typography } from 'antd';
import cn from 'classnames';

import { NotificationCard } from 'entities/Notification';
import { IDashboard } from 'pages/Dashboard';
import { EMainRoutes } from 'shared/typings';

import styles from './DasboardNotifications.module.scss';

const { Title } = Typography;

interface IDasboardNotificationsProps extends HTMLAttributes<HTMLDivElement> {
	dashboard?: IDashboard;
}

export const DasboardNotifications: FC<IDasboardNotificationsProps> = ({ className, dashboard, ...props }) => {
	const { t } = useTranslation();

	if (!dashboard?.notifications.length) return null;

	return (
		<Card {...props} className={cn(className, styles.dasboardNotifications)} styles={{ body: { padding: 24 } }}>
			<Flex vertical gap={16}>
				<Flex justify="space-between" align="center" gap={16}>
					<Title level={4} style={{ margin: 0 }}>
						{t('Уведомления')}
					</Title>
					<Link to={`/${EMainRoutes.NOTIFICATIONS}`}>{t('Смотреть все')}</Link>
				</Flex>

				<div className={styles.list}>
					{dashboard?.notifications.map((notification) => (
						<NotificationCard key={notification.id} notification={notification} isDashboard />
					))}
				</div>
			</Flex>
		</Card>
	);
};
