import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';

import { Flex } from 'antd';

import { EFilters } from 'features/Filters/types/enums';
import { useGetDashboardQuery } from 'pages/Dashboard/api/api';
import { DasboardCarousel } from 'widgets/DashboardCarousel';
import { DashboardCharts } from 'widgets/DashboardCharts';
import { DasboardNotifications } from 'widgets/DashboardNotifications';
import { DashboardOffers } from 'widgets/DashboardOffers';

import styles from './Dashboard.module.scss';

interface IDashboardProps extends HTMLAttributes<HTMLDivElement> {}

export const Dashboard: FC<IDashboardProps> = () => {
	const { t } = useTranslation();
	const { data, isFetching } = useGetDashboardQuery();

	return (
		<Flex vertical gap={24} className={styles.dashboard}>
			<DasboardCarousel banners={data?.banners || []} />
			<DashboardCharts dashboard={data} dashboardIsFetching={isFetching} />
			<DasboardNotifications dashboard={data} />
			{!!data?.recommended_offers?.length && (
				<DashboardOffers
					list={data?.recommended_offers}
					label={t('Affilead рекомендует')}
					filter={`${EFilters.RECOMMENDED}=true`}
					linkLabel={t('Все рекомендуемые офферы')}
				/>
			)}
			{!!data?.best_offers?.length && (
				<DashboardOffers list={data?.best_offers} label={t('Лучшие оффера за 7 дней')} isBests />
			)}
		</Flex>
	);
};

export default Dashboard;
