import { FC, HTMLAttributes } from 'react';
import { useTranslation } from 'react-i18next';
import { Link } from 'react-router-dom';

import { Flex, Typography } from 'antd';

import { IOffer, OfferCard } from 'entities/Offer';
import { useMedia } from 'shared/hooks';
import { EMainRoutes } from 'shared/typings';

import styles from './DashboardOffers.module.scss';

const { Title } = Typography;

interface IDashboardOffersProps extends HTMLAttributes<HTMLDivElement> {
	label: string;
	list: IOffer[];
	isBests?: boolean;
	filter?: string;
	linkLabel?: string;
}

export const DashboardOffers: FC<IDashboardOffersProps> = ({ label, list, isBests, filter, linkLabel, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();

	return (
		<Flex {...props} vertical gap={16}>
			<Flex vertical={isMd} justify="space-between" align={isMd ? 'flex-start' : 'center'} gap={isMd ? 4 : 16}>
				<Title level={4} style={{ margin: 0 }}>
					{label}
				</Title>
				<Link to={`/${EMainRoutes.CATALOG}${filter ? `?${filter}` : ''}`}>{linkLabel || t('Все оффера')}</Link>
			</Flex>

			<div className={styles.list}>
				{list.map((offer) => (
					<OfferCard key={offer.uuid} offer={offer} isDashboard isBests={isBests} />
				))}
			</div>
		</Flex>
	);
};
