import { FC, HTMLAttributes, ReactNode } from 'react';
import { useTranslation } from 'react-i18next';

import { Card, Flex, Typography } from 'antd';

import { useMedia } from 'shared/hooks';
import { ChangeArrow } from 'shared/ui';
import { formatNumber } from 'shared/utils';

interface IDashboardCardProps extends HTMLAttributes<HTMLDivElement> {
	header: ReactNode;
	value: number;
	oldValue: number;
	unit?: string;
}

export const DashboardCard: FC<IDashboardCardProps> = ({ header, value, oldValue, unit, ...props }) => {
	const { t } = useTranslation();
	const isMd = useMedia();

	return (
		<Card
			{...props}
			style={{ boxShadow: isMd ? 'none' : undefined, width: '100%' }}
			styles={{ body: { padding: 0 } }}
			bordered={!isMd}>
			<Flex vertical gap={4} style={{ padding: isMd ? '20px' : '20px' }}>
				<Typography.Text type="secondary">{header}</Typography.Text>
				<Typography.Title level={3} style={{ margin: 0 }}>
					{formatNumber(value)}
					{unit}
				</Typography.Title>
				<ChangeArrow
					oldValue={oldValue}
					newValue={value}
					label={<Typography.Text style={{ fontSize: 12 }}>{t('за месяц')}</Typography.Text>}
					unit={unit}
				/>
			</Flex>
		</Card>
	);
};
